"""Render only opted-in private workflow wrappers from the shared cadence policy."""

import argparse
import json
import re
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
RENOVATE = """---
# Generated by repo-automation src/private_workflows.py; private cadence policy.
name: Renovate
on:
  schedule:
    # Monday and Thursday, 02:xx AEST / 03:xx AEDT.
    - cron: "@CRON@"
  workflow_dispatch:
    inputs:
      log_level:
        description: Renovate log level
        default: info
        type: choice
        options: [info, debug]
permissions:
  actions: write
  contents: read
concurrency:
  group: renovate
  cancel-in-progress: false
jobs:
  renovate:
    uses: yuzuyuzuyu/repo-automation/.github/workflows/renovate-runner.yml@@REF@ # @VERSION@
    with:
      app-client-id: ${{ vars.RENOVATE_APP_CLIENT_ID }}
      native-automerge: false
      log_level: ${{ inputs.log_level || 'info' }}
      # A trusted manual run can process urgent updates outside routine windows.
      renovate-config: >-
        ${{ github.event_name == 'workflow_dispatch' && '{"force":{"schedule":["at any time"],"updateNotScheduled":true}}' || '{}' }}
    secrets:
      RENOVATE_APP_PRIVATE_KEY: ${{ secrets.RENOVATE_APP_PRIVATE_KEY }}
      RENOVATE_GITHUB_LOOKUP_TOKEN: ${{ secrets.RENOVATE_GITHUB_LOOKUP_TOKEN }}
"""
WATCHDOG = """---
# Generated by repo-automation src/private_workflows.py; private cadence policy.
name: Maintenance watchdog
on:
  schedule:
    - cron: "@CRON@"
  workflow_dispatch:
  workflow_run:
    workflows: @WORKFLOWS@
    types: [completed]
    branches: [main]
permissions:
  contents: read
  pull-requests: read
  issues: write
  actions: write
concurrency:
  group: maintenance-watchdog
  cancel-in-progress: false
jobs:
  maintenance:
    # React once to trusted main-branch failures; the controller also bounds retries.
    if: >-
      github.event_name != 'workflow_run' ||
      (github.event.workflow_run.conclusion == 'failure' &&
       github.event.workflow_run.run_attempt == 1 &&
       github.event.workflow_run.head_repository.full_name == github.repository &&
       contains(fromJSON('["push", "schedule", "workflow_dispatch"]'), github.event.workflow_run.event))
    runs-on: ubuntu-latest
    timeout-minutes: 10
    steps:
      - uses: yuzuyuzuyu/repo-automation/actions/watchdog@@REF@ # @VERSION@
"""


def render(repository: str, ref: str, version: str) -> dict[str, str]:
    if not re.fullmatch(r"[0-9a-f]{40}", ref):
        raise ValueError("Use an immutable full commit SHA")
    if not re.fullmatch(r"v\d+\.\d+\.\d+", version):
        raise ValueError("Use a published semantic version tag")
    policy = json.loads((ROOT / "private/workflows.json").read_text())[repository]
    common = {"@REF@": ref, "@VERSION@": version}
    templates = {
        "renovate.yml": (RENOVATE, {"@CRON@": policy["renovate_cron"]}),
        "maintenance.yml": (
            WATCHDOG,
            {
                "@CRON@": policy["watchdog_cron"],
                "@WORKFLOWS@": json.dumps(policy["workflows"]),
            },
        ),
    }
    rendered = {}
    for name, (source, substitutions) in templates.items():
        template = source
        for old, new in {**common, **substitutions}.items():
            template = template.replace(old, new)
        rendered[name] = template
    return rendered


def main() -> None:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument(
        "repository", choices=["yuzuyu", "passwordreset", "webhook-image-updater"]
    )
    parser.add_argument("directory", type=Path)
    parser.add_argument("--ref", required=True)
    parser.add_argument("--version", required=True)
    parser.add_argument("--check", action="store_true")
    args = parser.parse_args()
    rendered = render(args.repository, args.ref, args.version)
    workflows = args.directory / ".github/workflows"
    if args.repository == "yuzuyu":
        policy = json.loads((ROOT / "private/workflows.json").read_text())[
            args.repository
        ]
        source = (workflows / "dependency-pins.yml").read_text()
        rendered["dependency-pins.yml"], count = re.subn(
            r"(?m)^(    - cron: ).*$", rf'\g<1>"{policy["pin_cron"]}"', source
        )
        if count != 1:
            raise ValueError("Expected exactly one dependency-pin fallback schedule")
    for name, text in rendered.items():
        destination = workflows / name
        if args.check:
            if destination.read_text() != text:
                raise SystemExit(f"Private workflow differs from shared policy: {name}")
        else:
            destination.write_text(text)


if __name__ == "__main__":
    main()
